287: 
288: function normalizeTextModelConfig(raw: Partial<TextModelConfig>): TextModelConfig | null {
289:   const id = String(raw.id || '').trim();
290:   if (!id) return null;
291:   const protocol = isTextProviderProtocol(raw.protocol) ? raw.protocol : 'openai-responses';
292:   const template = getDefaultTextModelTemplate(protocol);
293:   return {
294:     id,
295:     protocol,
296:     name: String(raw.name || '').trim(),
297:     modelId: String(raw.modelId || '').trim(),
298:     apiKey: String(raw.apiKey || '').trim(),
299:     baseUrl: FIXED_MODEL_BASE_URL,
300:     note: typeof raw.note === 'string' ? raw.note : (template.note || getTextProviderDescription(protocol)),
301:   };
