304: function isCompleteImageModel(model: Partial<ImageModelConfig>): model is ImageModelConfig {
305:   return Boolean(
306:     model.id
307:     && model.name?.trim()
308:     && model.modelId?.trim()
309:     && model.apiKey?.trim()
310:     && model.baseUrl?.trim()
311:   );
312: }
313: 
314: function isCompleteTextModel(model: Partial<TextModelConfig>): model is TextModelConfig {
315:   return Boolean(
316:     model.id
317:     && model.name?.trim()
318:     && model.modelId?.trim()
319:     && model.apiKey?.trim()
320:     && model.baseUrl?.trim()
321:   );
