324: function ensureImageModels(raw?: unknown): ImageModelConfig[] {
325:   if (!Array.isArray(raw)) return [];
326:   return raw
327:     .map((item) => normalizeImageModelConfig((item || {}) as Partial<ImageModelConfig>))
328:     .filter((item): item is ImageModelConfig => Boolean(item))
329:     .filter((item, index, list) => list.findIndex((candidate) => candidate.id === item.id) === index);
330: }
331: 
332: function ensureTextModels(raw?: unknown): TextModelConfig[] {
333:   if (!Array.isArray(raw)) return [];
334:   return raw
335:     .map((item) => normalizeTextModelConfig((item || {}) as Partial<TextModelConfig>))
336:     .filter((item): item is TextModelConfig => Boolean(item))
337:     .filter((item, index, list) => list.findIndex((candidate) => candidate.id === item.id) === index);
338: }
339: 
340: function ensureDefaults(raw: Partial<DefaultModels> | undefined, imageModels: ImageModelConfig[], textModels: TextModelConfig[]): DefaultModels {
341:   const completeImageModels = imageModels.filter(isCompleteImageModel);
342:   const completeTextModels = textModels.filter(isCompleteTextModel);
343:   const firstImageModelId = completeImageModels[0]?.id || '';
344:   const firstTextModelId = completeTextModels[0]?.id || '';
345:   const next = { ...DEFAULT_DEFAULTS, ...raw };
346: 
347:   if (!completeImageModels.some((model) => model.id === next.textToImage)) next.textToImage = firstImageModelId;
348:   if (!completeImageModels.some((model) => model.id === next.imageToImage)) next.imageToImage = firstImageModelId;
349:   if (!completeTextModels.some((model) => model.id === next.reversePrompt)) next.reversePrompt = firstTextModelId;
350:   if (!completeTextModels.some((model) => model.id === next.agent)) next.agent = firstTextModelId;
351:   if (!completeTextModels.some((model) => model.id === next.promptOptimize)) next.promptOptimize = firstTextModelId;
352:   if (!completeTextModels.some((model) => model.id === next.imageDescribe)) next.imageDescribe = firstTextModelId;
353: 
354:   return next;
355: }
