357: function getInitialRegistry(): NovaModelRegistry {
358:   return {
359:     imageModels: [],
360:     textModels: [],
361:     defaults: DEFAULT_DEFAULTS,
362:   };
363: }
364: 
365: export function loadRegistry(): NovaModelRegistry {
366:   if (typeof window === 'undefined') {
