376:   const imageModels = ensureImageModels(parsed.imageModels);
377:   const textModels = ensureTextModels(parsed.textModels);
378:   const defaults = ensureDefaults(parsed.defaults, imageModels, textModels);
379:   return { imageModels, textModels, defaults };
380: }
