160: 
161: function roundToMultiple(value: number, multiple: number): number {
162:   return Math.max(multiple, Math.round(value / multiple) * multiple);
163: }
164: 
165: function parseImageSize(size?: string): { width: number; height: number } | undefined {
166:   const match = String(size || '').match(/^\s*(\d+)\s*[xX×]\s*(\d+)\s*$/);
167:   if (!match) return undefined;
168: 
169:   const width = Number(match[1]);
170:   const height = Number(match[2]);
171:   return Number.isFinite(width) && Number.isFinite(height) ? { width, height } : undefined;
172: }
173: 
174: function isImageSizeWithinLimits(width: number, height: number, maxSide?: number): boolean {
175:   if (!Number.isFinite(width) || !Number.isFinite(height) || width <= 0 || height <= 0) return false;
176: 
177:   const limit = typeof maxSide === 'number' && maxSide > 0 ? maxSide : Number.POSITIVE_INFINITY;
178:   const longSide = Math.max(width, height);
179:   const shortSide = Math.min(width, height);
180:   const pixels = width * height;
181: 
182:   return (
183:     longSide <= limit &&
184:     width % CUSTOM_IMAGE_SIZE_LIMITS.multiple === 0 &&
185:     height % CUSTOM_IMAGE_SIZE_LIMITS.multiple === 0 &&
186:     longSide / shortSide <= CUSTOM_IMAGE_SIZE_LIMITS.maxAspectRatio &&
187:     pixels >= CUSTOM_IMAGE_SIZE_LIMITS.minPixels &&
188:     pixels <= CUSTOM_IMAGE_SIZE_LIMITS.maxPixels
189:   );
190: }
191: 
192: function isGptImage2ProResolutionSupported(size?: string): boolean {
193:   const parsed = parseImageSize(size);
194:   return Boolean(parsed && isImageSizeWithinLimits(parsed.width, parsed.height, getCustomSizeMaxSide('gpt-image-2')));
195: }
196: 
197: export function getGptImageResolution(outputSize: OutputSize, aspectRatio: AspectRatio): string | undefined {
198:   if (outputSize === 'auto' || outputSize === '512' || aspectRatio === 'auto') return undefined;
199: 
200:   const [ratioWidth, ratioHeight] = aspectRatio.split(':').map(Number);
201:   if (!ratioWidth || !ratioHeight) return undefined;
202: 
203:   if (ratioWidth === ratioHeight) {
204:     const side = outputSize === '1K' ? 1024 : outputSize === '2K' ? 2048 : 3840;
205:     return `${side}x${side}`;
206:   }
207: 
208:   if (outputSize === '1K') {
209:     const shortSide = 1024;
210:     const width = ratioWidth > ratioHeight
211:       ? roundToMultiple(shortSide * ratioWidth / ratioHeight, 16)
212:       : shortSide;
213:     const height = ratioWidth > ratioHeight
214:       ? shortSide
215:       : roundToMultiple(shortSide * ratioHeight / ratioWidth, 16);
216:     return `${width}x${height}`;
217:   }
218: 
219:   const longSide = outputSize === '2K' ? 2048 : 3840;
220:   const width = ratioWidth > ratioHeight
221:     ? longSide
222:     : roundToMultiple(longSide * ratioWidth / ratioHeight, 16);
223:   const height = ratioWidth > ratioHeight
224:     ? roundToMultiple(longSide * ratioHeight / ratioWidth, 16)
225:     : longSide;
226:   return `${width}x${height}`;
227: }
228: 
229: export function normalizeCustomImageSize(size?: string, maxSide?: number): string | undefined {
230:   const parsed = parseImageSize(size);
231:   if (!parsed) return undefined;
232: 
233:   const limit = typeof maxSide === 'number' && maxSide > 0 ? maxSide : Number.POSITIVE_INFINITY;
234:   const width = Math.min(roundToMultiple(parsed.width, CUSTOM_IMAGE_SIZE_LIMITS.multiple), limit);
235:   const height = Math.min(roundToMultiple(parsed.height, CUSTOM_IMAGE_SIZE_LIMITS.multiple), limit);
236:   if (!isImageSizeWithinLimits(width, height, maxSide)) return undefined;
237: 
238:   return `${width}x${height}`;
239: }
