352: export function getAspectRatioOptions(model: ModelId, outputSize: OutputSize): AspectRatioOption[] {
353:   if (outputSize === 'auto') {
354:     return [{ value: 'auto', label: '自动', resolution: '自动' }];
355:   }
356: 
357:   const presetId = getBuiltinPresetId(model);
358: 
359:   if (presetId === 'gemini-2.5-flash-image') {
360:     return BANANA_ASPECT_RATIOS;
361:   }
362:   if (presetId === 'gemini-3-pro-image-preview') {
363:     return BANANA_PRO_ASPECT_RATIOS.map(ar => ({
364:       value: ar.value,
365:       label: ar.label,
366:       resolution: ar.resolutions[outputSize] || ar.resolutions['1K'],
367:     }));
368:   }
369:   if (isGptImage2Preset(presetId)) {
370:     return GPT_IMAGE_ASPECT_RATIOS.map(ar => ({
371:       value: ar.value,
372:       label: ar.label,
373:       resolution: getGptImageResolution(outputSize, ar.value) || '',
374:     })).filter(option => isGptImage2ProResolutionSupported(option.resolution));
375:   }
376:   if (isGrokImagePreset(presetId)) {
377:     return GROK_IMAGE_ASPECT_RATIOS.map(ar => ({
378:       value: ar.value,
379:       label: ar.label,
380:       resolution: outputSize === '2K' ? '2K' : '1K',
381:     }));
382:   }
383:   if (presetId === 'gemini-3.1-flash-image-preview' || presetId === 'gemini-3.1-flash-lite-image') {
384:     return BANANA2_ASPECT_RATIOS.map(ar => ({
385:       value: ar.value,
386:       label: ar.label,
387:       resolution: ar.resolutions[outputSize] || ar.resolutions['1K'],
388:     }));
389:   }
390: 
391:   return BANANA_ASPECT_RATIOS;
392: }
