438: export function isRetryLayoutCompatible(model: ModelId, outputSize: OutputSize, aspectRatio: AspectRatio): boolean {
439:   const presetId = getBuiltinPresetId(model);
440:   if (outputSize === 'auto' || aspectRatio === 'auto') {
441:     return supportsAutoLayout(model) && outputSize === 'auto' && aspectRatio === 'auto';
442:   }
443: 
444:   if (presetId === 'gemini-2.5-flash-image') {
445:     return outputSize === '1K';
446:   }
447: 
448:   if (presetId === 'gemini-3-pro-image-preview') {
449:     return ['1K', '2K', '4K'].includes(outputSize);
450:   }
451: 
452:   if (isGptImage2Preset(presetId)) {
453:     const resolution = getGptImageResolution(outputSize, aspectRatio);
454:     return ['1K', '2K', '4K'].includes(outputSize) && isGptImage2ProResolutionSupported(resolution);
455:   }
456: 
457:   if (presetId === 'gemini-3.1-flash-image-preview') {
458:     return ['512', '1K', '2K', '4K'].includes(outputSize);
459:   }
460: 
461:   if (presetId === 'gemini-3.1-flash-lite-image') {
462:     return outputSize === '1K';
463:   }
464: 
465:   if (presetId === 'grok-imagine-image') {
466:     return outputSize === '1K';
467:   }
468: 
469:   if (presetId === 'grok-imagine-image-quality' || presetId === 'grok-imagine-image-edit') {
470:     return outputSize === '1K' || outputSize === '2K';
471:   }
472: 
473:   return outputSize === '1K';
474: }
