478:   if (typeof modelLimits[model]?.max === 'number') return Math.max(0, modelLimits[model].max);
479:   const configured = getModelConfig(model)?.maxRefImages;
480:   if (typeof configured === 'number' && configured >= 0) return configured;
481:   return 1;
