552: export function getSupportsTemperature(model: ModelId): boolean {
553:   if (isGptImageModel(model)) return false;
554:   const presetId = getBuiltinPresetId(model);
555:   if (isGrokImagePreset(presetId)) return false;
556:   const modelConfig = getModelConfig(model);
557:   if (modelConfig?.protocol === 'grok') return false;
558:   return true;
