394: export function detectClosestAspectRatio(width: number, height: number, options: AspectRatioOption[]): AspectRatio {
395:   if (width <= 0 || height <= 0 || options.length === 0) {
396:     return '1:1';
397:   }
398: 
399:   const targetRatio = width / height;
400:   let closestRatio: AspectRatio = options[0]?.value || '1:1';
401:   let closestDistance = Number.POSITIVE_INFINITY;
402: 
403:   for (const option of options) {
404:     if (option.value === 'auto') continue;
405: 
406:     const [ratioWidth, ratioHeight] = option.value.split(':').map(Number);
407:     if (!ratioWidth || !ratioHeight) continue;
408: 
409:     const candidateRatio = ratioWidth / ratioHeight;
410:     const distance = Math.abs(candidateRatio - targetRatio);
411:     if (distance < closestDistance) {
412:       closestDistance = distance;
413:       closestRatio = option.value;
414:     }
415:   }
416: 
417:   return closestRatio;
418: }
