561: // ===== Agent 提案参数合法化 =====
562: 
563: /** Agent 可用的图像模型目录项，注入到系统指令中供模型选择 */
564: export interface AgentModelCatalogEntry {
565:   /** 模型注册 ID（用于 requested_model_id） */
566:   id: string;
567:   /** 用户可见的模型名称/别名 */
568:   name: string;
569:   /** 最大输出分辨率: '512' | '1K' | '2K' | '4K' */
570:   maxOutputSize: string;
571: }
572: 
573: export interface AgentLayoutIntent {
574:   /** 用户语言明确指定的比例（优先级 1），如 "16:9" */
575:   requestedAspectRatio?: string;
576:   /** Agent 智能推荐的比例（优先级 3），如 "2:3" */
577:   suggestedAspectRatio?: string;
578:   /** 用户明确要求的清晰度档位，如 "4K"/"2K"/"1K"/"512"/"auto" */
579:   requestedOutputSize?: string;
580:   /** 建议温度 0-2 */
581:   temperature?: number;
582:   /** 建议并行数量 1-4 */
583:   parallelCount?: number;
584: }
585: 
586: export interface AgentResolvedLayout {
587:   outputSize: OutputSize;
588:   customSize?: string;
589:   aspectRatio: AspectRatio;
590:   temperature: number;
591:   gptImageQuality: GptImageQuality;
592:   gptImageStyle: GptImageStyle;
593:   gptImageBackground: GptImageBackground;
594:   parallelCount: ParallelCount;
595: }
596: 
597: function parseRatioString(value?: string): { width: number; height: number } | undefined {
598:   const match = String(value || '').match(/^\s*(\d+(?:\.\d+)?)\s*[:：xX×/]\s*(\d+(?:\.\d+)?)\s*$/);
599:   if (!match) return undefined;
600:   const width = Number(match[1]);
601:   const height = Number(match[2]);
602:   if (!Number.isFinite(width) || !Number.isFinite(height) || width <= 0 || height <= 0) return undefined;
603:   return { width, height };
604: }
605: 
606: function clampNumber(value: number, min: number, max: number): number {
607:   return Math.min(max, Math.max(min, value));
608: }
609: 
610: // ===== Agent 模型自动选择 =====
611: 
612: const OUTPUT_SIZE_RANK: Record<string, number> = { '512': 0, '1K': 1, '2K': 2, '4K': 3 };
613: 
614: function canModelSupportSize(maxOutputSize: string, requestedSize: string): boolean {
615:   return (OUTPUT_SIZE_RANK[maxOutputSize] ?? 0) >= (OUTPUT_SIZE_RANK[requestedSize] ?? 0);
616: }
617: 
618: /**
619:  * 按优先级解析 Agent 提案中的模型意图，自动选择最合适的图像模型：
620:  * 1. Agent 明确指定了模型 id 且该 id 存在 → 直接使用
621:  * 2. 用户要求了分辨率档位但当前模型不支持 → 自动选择支持该档位且「够用就好」的模型
622:  * 3. 以上都不满足 → 保持当前模型
623:  */
624: export function resolveAgentModel(
625:   currentModel: ModelId,
626:   requestedModelId: string | undefined,
627:   requestedOutputSize: string | undefined,
628:   availableModels: AgentModelCatalogEntry[],
629: ): ModelId {
630:   // 1) Agent 明确指定了模型 → 验证后使用
631:   if (requestedModelId) {
632:     const found = availableModels.find(m => m.id === requestedModelId);
633:     if (found) return found.id;
634:   }
635: 
636:   // 2) 用户要求了分辨率档位，当前模型不支持 → 自动选择支持的模型
637:   if (requestedOutputSize && requestedOutputSize !== 'auto' && availableModels.length > 0) {
638:     const current = availableModels.find(m => m.id === currentModel);
639:     const currentCanSupport = current
640:       ? canModelSupportSize(current.maxOutputSize, requestedOutputSize)
641:       : true;
642:     if (!currentCanSupport) {
643:       const candidates = availableModels.filter(m =>
644:         canModelSupportSize(m.maxOutputSize, requestedOutputSize),
645:       );
646:       if (candidates.length > 0) {
647:         // 优先选择最大分辨率刚好满足需求的模型（避免不必要的 4K 模型）
648:         candidates.sort(
649:           (a, b) => (OUTPUT_SIZE_RANK[a.maxOutputSize] ?? 0) - (OUTPUT_SIZE_RANK[b.maxOutputSize] ?? 0),
650:         );
651:         return candidates[0].id;
652:       }
653:     }
654:   }
655: 
656:   // 3) 无需切换
657:   return currentModel;
658: }
659: 
660: /**
661:  * 按「用户语言 > 上传图分辨率 > Agent 智能选择」的优先级，把 Agent 的参数意图
662:  * 合法化成当前所选模型实际支持的布局。不合法的比例/档位会贴合到最近的合法值。
663:  */
664: export function resolveAgentLayout(
665:   model: ModelId,
666:   intent: AgentLayoutIntent,
667:   refDims?: { width?: number; height?: number },
668: ): AgentResolvedLayout {
669:   const defaults = getDefaultRetryLayout(model);
670:   const validSizes = getValidOutputSizes(model);
671: 
672:   // 1) 清晰度档位：仅当用户明确要求且该模型支持时采用，否则用默认
673:   let outputSize: OutputSize = defaults.outputSize;
674:   const requestedSize = intent.requestedOutputSize as OutputSize | undefined;
675:   if (requestedSize && validSizes.includes(requestedSize)) {
676:     outputSize = requestedSize;
677:   }
678: 
679:   const explicitRatio = parseRatioString(intent.requestedAspectRatio);
680: 
681:   // 默认 auto 时：若用户用语言明确指定了比例（优先级 1），auto 会吞掉该比例，
682:   // 故切换到最小的具体档位让比例生效；其余情况保持模型默认 auto。
683:   if (outputSize === 'auto' && explicitRatio && !requestedSize) {
684:     const concreteSizes = validSizes.filter(size => size !== 'auto');
685:     if (concreteSizes.length > 0) {
686:       outputSize = concreteSizes.includes('1K') ? '1K' : concreteSizes[0];
687:     }
688:   }
689: 
690:   // auto 档无需比例，直接返回
691:   if (outputSize === 'auto') {
692:     return {
693:       outputSize,
694:       aspectRatio: 'auto',
695:       temperature: getSupportsTemperature(model) ? clampNumber(intent.temperature ?? 1, 0, 2) : 1,
696:       gptImageQuality: DEFAULT_GPT_IMAGE_ADVANCED_PARAMS.quality,
697:       gptImageStyle: DEFAULT_GPT_IMAGE_ADVANCED_PARAMS.style,
698:       gptImageBackground: DEFAULT_GPT_IMAGE_ADVANCED_PARAMS.background,
699:       parallelCount: normalizeParallelCount(intent.parallelCount),
700:     };
701:   }
702: 
703:   const ratioOptions = getAspectRatioOptions(model, outputSize).filter(option => option.value !== 'auto');
704: 
705:   // 2) 纵横比优先级：用户语言 > 上传图分辨率 > Agent 智能 > 模型默认
706:   let aspectRatio: AspectRatio = defaults.aspectRatio === 'auto'
707:     ? (ratioOptions[0]?.value || '1:1')
708:     : defaults.aspectRatio;
709: 
710:   const requestedRatio = explicitRatio;
711:   const refRatio = refDims && refDims.width && refDims.height
712:     ? { width: refDims.width, height: refDims.height }
713:     : undefined;
714:   const suggestedRatio = parseRatioString(intent.suggestedAspectRatio);
715: 
716:   const ratioSource = requestedRatio || refRatio || suggestedRatio;
717:   if (ratioSource && ratioOptions.length > 0) {
718:     aspectRatio = detectClosestAspectRatio(ratioSource.width, ratioSource.height, ratioOptions);
719:   } else if (ratioOptions.length > 0 && !ratioOptions.some(option => option.value === aspectRatio)) {
720:     aspectRatio = ratioOptions[0].value;
721:   }
722: 
723:   // 3) 自定义尺寸：仅支持自定义尺寸的模型，且能从有效来源算出合法尺寸时填充
724:   let customSize: string | undefined;
725:   if (supportsCustomSize(model)) {
726:     const maxSide = getCustomSizeMaxSide(model);
727:     const dimsForCustom = requestedRatio ? undefined : refRatio;
728:     if (dimsForCustom) {
729:       customSize = normalizeCustomImageSize(`${Math.round(dimsForCustom.width)}x${Math.round(dimsForCustom.height)}`, maxSide);
730:     }
731:   }
732: 
733:   const temperature = getSupportsTemperature(model)
734:     ? clampNumber(intent.temperature ?? 1, 0, 2)
735:     : 1;
736: 
737:   return {
738:     outputSize,
739:     customSize,
740:     aspectRatio,
741:     temperature,
742:     gptImageQuality: DEFAULT_GPT_IMAGE_ADVANCED_PARAMS.quality,
743:     gptImageStyle: DEFAULT_GPT_IMAGE_ADVANCED_PARAMS.style,
744:     gptImageBackground: DEFAULT_GPT_IMAGE_ADVANCED_PARAMS.background,
745:     parallelCount: normalizeParallelCount(intent.parallelCount),
746:   };
747: }
748: 
749: function normalizeParallelCount(value?: number): ParallelCount {
750:   const rounded = Math.round(Number(value) || 1);
751:   const clamped = clampNumber(rounded, 1, 4);
752:   return clamped as ParallelCount;
753: }

