202: export async function checkModelsAvailability(
203:   targetModelIds?: string[],
204: ): Promise<ModelStatus[]> {
205:   try {
206:     const registry = loadRegistry();
207:     const completeImageModels = getCompleteImageModels(registry);
208:     const completeTextModels = getCompleteTextModels(registry);
209:     const configuredModels = [
210:       ...completeImageModels.map((model) => ({
211:         id: model.id,
212:         name: model.name,
213:         protocol: model.protocol,
214:         baseUrl: model.baseUrl,
215:         apiKey: model.apiKey,
216:         modelId: model.modelId,
217:       })),
218:       ...completeTextModels.map((model) => ({
219:         id: model.id,
220:         name: model.name,
221:         protocol: model.protocol,
222:         baseUrl: model.baseUrl,
223:         apiKey: model.apiKey,
224:         modelId: model.modelId,
225:       })),
226:     ];
227: 
228:     const filteredModels = targetModelIds && targetModelIds.length > 0
229:       ? configuredModels.filter((model) => targetModelIds.includes(model.id))
230:       : configuredModels;
231: 
232:     if (filteredModels.length === 0) {
233:       return [];
234:     }
235: 
236:     return Promise.all(filteredModels.map(async (model) => {
237:       try {
238:         const normalizedBaseUrl = completeImageModels.some(imageModel => imageModel.id === model.id)
239:           ? normalizeModelBaseUrl(model.protocol as ProviderProtocol, model.baseUrl)
240:           : normalizeTextModelBaseUrl(model.protocol as TextProviderProtocol, model.baseUrl);
241:         if (!normalizedBaseUrl || !model.apiKey || !model.modelId) {
242:           return {
243:             modelId: model.id,
244:             actualName: model.name,
245:             available: false,
246:             message: '模型配置不完整',
247:           };
248:         }
249: 
250:         // 统一通过后端代理使用 /v1/models（NewAPI 兼容）
251:         const modelType = completeImageModels.some(imageModel => imageModel.id === model.id) ? 'image' : 'text';
252:         const proxyUrl = `/api/nova/proxy/models?baseUrl=${encodeURIComponent(normalizedBaseUrl)}&apiKey=${encodeURIComponent(model.apiKey)}&protocol=${model.protocol}&modelType=${modelType}`;
253:         const response = await fetch(proxyUrl, { method: 'GET', cache: 'no-store' });
254:         if (!response.ok) {
255:           const detail = await response.text().catch(() => '');
256:           return {
257:             modelId: model.id,
258:             actualName: model.name,
259:             available: false,
260:             message: `${response.status}${detail ? ` ${detail.slice(0, 120)}` : ''}`,
261:           };
262:         }
263:         const data = await response.json().catch(() => ({})) as {
264:           data?: Array<{ id?: string; model?: string }>;
265:           models?: Array<{ name?: string }>;
266:         };
267:         const exists = (
268:           (Array.isArray(data.data) && data.data.some(
269:             (item) => String(item?.id || item?.model || '') === model.modelId,
270:           ))
271:           || (Array.isArray(data.models) && data.models.some(
272:             (item) => String(item?.name || '').replace(/^models\//, '') === model.modelId,
273:           ))
274:         );
275:         return {
276:           modelId: model.id,
277:           actualName: model.name,
278:           available: exists,
279:           message: exists ? model.modelId : `未在 /models 中找到 ${model.modelId}`,
280:         };
281:       } catch (error) {
282:         return {
283:           modelId: model.id,
284:           actualName: model.name,
285:           available: false,
286:           message: getErrorMessage(error),
287:         };
288:       }
289:     }));
290:   } catch (error) {
291:     throw normalizeModelCheckError(error);
292:   }
293: }
