297:   if (modelConfig) {
298:     if (isGrokImagePreset(modelConfig.builtinPreset)) {
299:       const values: OutputSize[] = modelConfig.maxOutputSize === '2K' || modelConfig.maxOutputSize === '4K'
300:         ? ['1K', '2K']
301:         : ['1K'];
302:       return values.map((value) => ({ value, label: value }));
303:     }
304:     const values: OutputSize[] = modelConfig.maxOutputSize === '4K'
305:       ? (modelConfig.builtinPreset === 'gemini-3.1-flash-image-preview' ? ['512', '1K', '2K', '4K'] : ['1K', '2K', '4K'])
306:       : modelConfig.maxOutputSize === '2K'
307:         ? (modelConfig.builtinPreset === 'gemini-3.1-flash-image-preview' ? ['512', '1K', '2K'] : ['1K', '2K'])
308:         : modelConfig.maxOutputSize === '512'
309:           ? ['512']
310:           : (modelConfig.builtinPreset === 'gemini-3.1-flash-image-preview' ? ['512', '1K'] : ['1K']);
311:     return values.map((value) => ({ value, label: value === '512' ? '0.5K' : value }));
312:   }
313: 
314:   const presetId = getBuiltinPresetId(model);
315:   if (presetId === 'grok-imagine-image') {
316:     return [{ value: '1K', label: '1K' }];
317:   }
318:   if (presetId === 'grok-imagine-image-quality' || presetId === 'grok-imagine-image-edit') {
319:     return [
320:       { value: '1K', label: '1K' },
321:       { value: '2K', label: '2K' },
322:     ];
323:   }
324:   if (presetId === 'gemini-3.1-flash-image-preview') {
325:     return [
326:       { value: '512', label: '0.5K' },
327:       { value: '1K', label: '1K' },
328:       { value: '2K', label: '2K' },
329:       { value: '4K', label: '4K' },
330:     ];
331:   }
332:   if (presetId === 'gemini-3-pro-image-preview' || isGptImage2Preset(presetId)) {
333:     return [
334:       { value: '1K', label: '1K' },
335:       { value: '2K', label: '2K' },
336:       { value: '4K', label: '4K' },
337:     ];
338:   }
339:   return [{ value: '1K', label: '1K' }];
340: }
