488: /** Prefer current model if it accepts refs; otherwise default i2i model or first capable model. */
489: export function findReferenceCapableModel(preferredId?: string): ModelId | null {
490:   const registry = loadRegistry();
491:   const complete = registry.imageModels.filter((model) =>
492:     Boolean(model.name.trim() && model.modelId.trim() && model.apiKey.trim() && model.baseUrl.trim()),
493:   );
494:   const capable = complete.filter((model) => model.maxRefImages > 0);
495:   if (capable.length === 0) return null;
496: 
497:   if (preferredId) {
498:     const preferred = capable.find((model) => model.id === preferredId);
499:     if (preferred) return preferred.id;
500:   }
501: 
502:   const defaultI2i = registry.defaults.imageToImage;
503:   if (defaultI2i) {
504:     const fromDefault = capable.find((model) => model.id === defaultI2i);
505:     if (fromDefault) return fromDefault.id;
506:   }
507: 
508:   const grokEdit = capable.find((model) => model.builtinPreset === 'grok-imagine-image-edit');
509:   if (grokEdit) return grokEdit.id;
510: 
511:   return capable[0].id;
512: }
