521:   const outputSize: OutputSize = shouldKeepLayout ? job.output_size : defaultLayout.outputSize;
522:   const aspectRatio: AspectRatio = shouldKeepLayout ? job.aspect_ratio : defaultLayout.aspectRatio;
523:   const customSize = shouldKeepLayout && supportsCustomSize(model)
524:     ? normalizeCustomImageSize(job.custom_size, getCustomSizeMaxSide(model))
525:     : undefined;
526:   const temperature = supportsTemperature && typeof job.temperature === 'number' ? job.temperature : 1;
527:   const parallelCount: ParallelCount = [1, 2, 3, 4].includes(job.parallelCount as ParallelCount)
528:     ? (job.parallelCount as ParallelCount)
529:     : 1;
530:   const advancedParams = getGptImageAdvancedParamsForModel(model, {
531:     quality: job.gptImageQuality,
532:     style: job.gptImageStyle,
533:     background: job.gptImageBackground,
534:   });
535: 
536:   return {
537:     mode: job.mode,
538:     prompt: job.originalPrompt || job.prompt,
539:     model,
540:     outputSize,
541:     aspectRatio,
542:     customSize,
543:     temperature,
544:     parallelCount,
545:     gptImageQuality: advancedParams.quality,
546:     gptImageStyle: advancedParams.style,
547:     gptImageBackground: advancedParams.background,
548:     refImages: job.refImages?.slice(0, maxRefs),
549:   };
