690:   // auto 档无需比例，直接返回
691:   if (outputSize === 'auto') {
692:     return {
693:       outputSize,
694:       aspectRatio: 'auto',
695:       temperature: getSupportsTemperature(model) ? clampNumber(intent.temperature ?? 1, 0, 2) : 1,
696:       gptImageQuality: DEFAULT_GPT_IMAGE_ADVANCED_PARAMS.quality,
697:       gptImageStyle: DEFAULT_GPT_IMAGE_ADVANCED_PARAMS.style,
698:       gptImageBackground: DEFAULT_GPT_IMAGE_ADVANCED_PARAMS.background,
699:       parallelCount: normalizeParallelCount(intent.parallelCount),
700:     };
701:   }
702: 
703:   const ratioOptions = getAspectRatioOptions(model, outputSize).filter(option => option.value !== 'auto');
704: 
705:   // 2) 纵横比优先级：用户语言 > 上传图分辨率 > Agent 智能 > 模型默认
706:   let aspectRatio: AspectRatio = defaults.aspectRatio === 'auto'
